            dp[i][1] = min(dp[i-1][0], dp[i-1][1])  # Do nothing
        elif activities[i] == 1:
            dp[i][0] = min(dp[i-1][0], dp[i-1][1])  # Do nothing
            dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + 1  # Write contest
        elif activities[i] == 2:
            dp[i][0] = min(dp[i-1][0], dp[i-1][1])  # Do nothing
            dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + 1  # Do sport
        elif activities[i] == 3:
            dp[i][0] = min(dp[i-1][0], dp[i-1][1])  # Do nothing
            dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + 1  # Write contest or do sport

        # Ensure no consecutive activities
        if i > 1:
            if activities[i] in [1, 3] and activities[i-1] in [1, 3]:
                dp[i][1] = float('inf')
            if activities[i] in [2, 3] and activities[i-1] in [2, 3]:
                dp[i][1] = float('inf')

    # Return the minimum of resting or doing nothing on the last day
    return min(dp[n-1][0], dp[n-1][1])

